From ff91cfad609c2466276551b80c27e09332593f97 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:53:01 +0100
Subject: [PATCH] runscript: allow skipping the inactivity command while apps
 block it

The "When inactive" command ran even while an app was blocking sleep or
screen locking, so a screensaver script could start over a video. Add a
checkbox to the command's settings that, when unchecked, skips it then.

BUG: 521388
---
 PowerDevilProfileSettings.kcfg       |  3 +++
 daemon/actions/bundled/runscript.cpp |  5 +++++
 daemon/actions/bundled/runscript.h   |  1 +
 kcm/ui/ProfileConfig.qml             | 18 ++++++++++++++++++
 4 files changed, 27 insertions(+)

diff --git a/PowerDevilProfileSettings.kcfg b/PowerDevilProfileSettings.kcfg
index 0ad1848ca..54850c3df 100644
--- a/PowerDevilProfileSettings.kcfg
+++ b/PowerDevilProfileSettings.kcfg
@@ -122,5 +122,8 @@ SPDX-License-Identifier: CC0-1.0
         <entry name="RunScriptIdleTimeoutSec" type="Int">
             <default>600</default>
         </entry>
+        <entry name="InhibitIdleTimeoutCommandWhenAppsBlock" type="Bool">
+            <default>false</default>
+        </entry>
     </group>
 </kcfg>
diff --git a/daemon/actions/bundled/runscript.cpp b/daemon/actions/bundled/runscript.cpp
index 7e1805eeb..f3db348f3 100644
--- a/daemon/actions/bundled/runscript.cpp
+++ b/daemon/actions/bundled/runscript.cpp
@@ -37,6 +37,10 @@ void RunScript::onProfileUnload()
 void RunScript::onIdleTimeout(std::chrono::milliseconds timeout)
 {
     Q_UNUSED(timeout);
+    if (m_inhibitIdleTimeoutCommand && PolicyAgent::instance()->unavailablePolicies() & (PolicyAgent::InterruptSession | PolicyAgent::ChangeScreenSettings)) {
+        qCDebug(POWERDEVIL) << "RunScript: inhibited, not running the idle timeout command";
+        return;
+    }
     runCommand(m_idleTimeoutCommand);
 }

@@ -52,6 +56,7 @@ bool RunScript::loadAction(const PowerDevil::ProfileSettings &profileSettings)
     m_profileLoadCommand = profileSettings.profileLoadCommand();
     m_profileUnloadCommand = profileSettings.profileUnloadCommand();
     m_idleTimeoutCommand = profileSettings.idleTimeoutCommand();
+    m_inhibitIdleTimeoutCommand = profileSettings.inhibitIdleTimeoutCommandWhenAppsBlock();

     if (m_profileLoadCommand.isEmpty() && m_profileUnloadCommand.isEmpty() && m_idleTimeoutCommand.isEmpty()) {
         return false;
diff --git a/daemon/actions/bundled/runscript.h b/daemon/actions/bundled/runscript.h
index 27cbdf418..502c3b3db 100644
--- a/daemon/actions/bundled/runscript.h
+++ b/daemon/actions/bundled/runscript.h
@@ -32,6 +32,7 @@ private:
     QString m_profileLoadCommand;
     QString m_profileUnloadCommand;
     QString m_idleTimeoutCommand;
+    bool m_inhibitIdleTimeoutCommand = false;
 };

 }
diff --git a/kcm/ui/ProfileConfig.qml b/kcm/ui/ProfileConfig.qml
index c88120439..3d5baed24 100644
--- a/kcm/ui/ProfileConfig.qml
+++ b/kcm/ui/ProfileConfig.qml
@@ -922,4 +922,22 @@ Kirigami.FormLayout {
             function onIdleTimeoutCommandChanged() { idleTimeoutCommandEdit.resetToProfileSettings(); }
         }
     }
+
+    QQC2.CheckBox {
+        id: idleTimeoutCommandWhenAppsBlockCheck
+        text: i18nc(
+            "@text:checkbox Run the command or script when inactive even when apps block sleep or screen locking",
+            "Even when apps are blocking sleep or screen locking"
+        )
+        Accessible.name: i18n("Run command or script when inactive even when apps are blocking sleep or screen locking")
+
+        visible: idleTimeoutCommandEdit.visible
+
+        KCM.SettingStateBinding {
+            configObject: root.profileSettings
+            settingName: "InhibitIdleTimeoutCommandWhenAppsBlock"
+        }
+        checked: !root.profileSettings.inhibitIdleTimeoutCommandWhenAppsBlock
+        onToggled: { root.profileSettings.inhibitIdleTimeoutCommandWhenAppsBlock = !checked; }
+    }
 }
-- 
2.53.0
